use std::collections::HashSet;

/// Remove duplicates from the input vector.
/// 
/// # Properties:
/// - The resulting vector has no duplicate elements.
/// - The set of elements in the result is equal to the set of elements in the input.
/// 
/// The output preserves the first occurrence order of each element.
/// 
/// # Arguments
/// 
/// * `nums` - A vector of i32 integers (possibly empty, with duplicates).
/// 
/// # Returns
/// 
/// * A vector of i32 containing the unique elements from `nums`.
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();
    
    for &num in &nums {
        if seen.insert(num) {
            // insert returns true if the value was not present
            result.push(num);
        }
    }
    
    result
}